import{_ as i,o as a,c as r,a5 as n}from"./chunks/framework.DrDMl0tG.js";const p=JSON.parse('{"title":"RaiSim Engine 2","description":"","frontmatter":{},"headers":[],"relativePath":"sections/RaisimEngine2.md","filePath":"sections/RaisimEngine2.md"}'),t={name:"sections/RaisimEngine2.md"};function o(s,e,l,d,c,m){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="raisim-engine-2" tabindex="-1">RaiSim Engine 2 <a class="header-anchor" href="#raisim-engine-2" aria-label="Permalink to &quot;RaiSim Engine 2&quot;">​</a></h1><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>RaiSim Engine 2 is an internal, closed-source world-authoring tool. It builds RaiSim worlds, for example worlds to train in with <a href="./RaisimGymTorch.html">RaisimGymTorch</a>, but it does not train policies itself. It is not part of the public <code>raisim2Lib</code> distribution. The public repository does not ship Engine 2 executables, headers, libraries, CMake targets, examples, or tests, so users cannot build or invoke it from <code>raisim2Lib</code>.</p><p>The public package boundary is the downloaded RaiSim and rayrai binaries and headers together with the example, wrapper, resource, and documentation sources in <code>raisim2Lib</code>. Engine 2 implementation paths and internal build options are therefore intentionally not documented as user workflows.</p><h2 id="public-alternatives" tabindex="-1">Public Alternatives <a class="header-anchor" href="#public-alternatives" aria-label="Permalink to &quot;Public Alternatives&quot;">​</a></h2><p>Use the supported public interfaces instead:</p><ul><li>construct and modify a <code>raisim::World</code> through the C++ or RaisimPy API;</li><li>load RaiSim XML, MJCF, or OpenUSD scenes as documented in <a href="./WorldConfigurationFile.html">World Configuration File</a> and <a href="./OpenUSD.html">OpenUSD Loading</a>;</li><li>use <a href="./Rayrai.html">rayrai Visualizer</a> or <a href="./RayraiTcpViewer.html">Rayrai TCP Viewer</a> for visualization; and</li><li>use <a href="./RaisimGymTorch.html">RaisimGymTorch</a> for reinforcement-learning training.</li></ul><p><code>.re2</code> is an internal Engine 2 format. <code>.rscene</code> is the scene file Engine 2 writes. RaiSim and rayrai read it through <code>raisim::World(path)</code> and a <code>raisin::RayraiWindow</code> on that world, available from v2.8.2 (not yet released; v2.8.0 and v2.8.1 read the file and show it with <code>raisin::applyRscene</code>), and show what Engine 2&#39;s viewport shows, except articulated systems, compounds, deformables, granular media, decals, irradiance volumes and point clouds. <a href="./RsceneFile.html">.rscene File</a> documents the format and the supported records, and <a href="./examples/rayrai/rayrai_forest_from_rscene.html">Rayrai Example: Forest From .rscene</a> loads a scene file shipped in <code>rsc/forest</code>.</p>',8)])])}const u=i(t,[["render",o]]);export{p as __pageData,u as default};
